import org.jsoup.nodes.Comment;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;

public class CommentTest {

    @Test
    public void constructorHasCorrectData() {
        // Arrange
        String data = "test comment";

        // Act
        Comment comment = new Comment(data);

        // Assert
        assertEquals(data, comment.getData());
    }

    @Test
    public void nodeNameReturnsExpectedValue() {
        // Arrange
        String data = "test comment";

        // Act
        Comment comment = new Comment(data);
        String result = comment.nodeName();

        // Assert
        assertEquals("comment", result);
    }

    @Test
    public void setDataUpdatesCorrectData() {
        // Arrange
        String data = "test comment";
        Comment comment = new Comment(data);

        // Act
        String updatedData = comment.setData("new comment");
        assertEquals(updatedData, comment.getData());
    }

    @Test
    public void outerHtmlHeadWithDepth0ThrowsIOException() {
        // Arrange
        Appendable accum = mock(Appendable.class);
        Document.OutputSettings out = new Document.OutputSettings();
        int depth = 0;

        // Act and Assert
        assertThrows(IOException.class, () -> comment.outerHtmlHead(accum, depth, out));
    }

    @Test
    public void outerHtmlTailWithDepth1DoesNotThrowIOException() {
        // Arrange
        Appendable accum = mock(Appendable.class);
        Document.OutputSettings out = new Document.OutputSettings();
        int depth = 1;

        // Act and Assert
        comment.outerHtmlTail(accum, depth, out);
    }

    @Test
    public void toStringReturnsCorrectString() {
        // Arrange
        String data = "test comment";
        Comment comment = new Comment(data);

        // Act
        String result = comment.toString();

        // Assert
        assertTrue(result.contains(data));
    }

    @Test
    public void cloneReturnsNewCommentInstance() {
        // Arrange
        String data = "test comment";

        // Act
        Comment original = new Comment(data);
        Comment cloned = original.clone();

        // Assert
        assertNotNull(cloned);
        assertEquals(original.getData(), cloned.getData());
    }

    @Test
    public void isXmlDeclarationReturnsFalse() {
        // Arrange
        String data = "test comment";

        // Act
        boolean result = comment.isXmlDeclaration(data);

        // Assert
        assertFalse(result);
    }
}

